            (9, 8, 7, 6),
            (10**12, 0, 0, 0),
        ):
            with self.subTest(weights=weights):
                self.assertEqual(
                    recommend_merkle_deployment_weighted(1, budgets, weights),
                    frontier[0],
                )

    def test_tie_break_is_documented_tail(self):
