            weighted = Fraction(0)
            for value, weight, (low, high) in zip(
                _metrics(storage), weights, spans
            ):
                if high > low:
                    weighted += weight * Fraction(value - low, high - low)
            value = weighted / total
            self.assertIsInstance(value, Fraction)
            return value

