    def test_no_feasible_candidate_raises(self):
        with self.assertRaises(ValueError):
            recommend_merkle_deployment_weighted(
                1, (100, None, None, None), (1, 1, 1, 1)
            )
        with self.assertRaises(ValueError):
            recommend_merkle_deployment_weighted(
